# Generates a SHA256SUMS file compatible with `sha256sum -c`, using LF line endings.
#
# Why: when generated by hand on Windows, SHA256SUMS inherits CRLF line endings.
# The invisible `\r` breaks the `$` anchor of a `grep '...$'` and makes verification
# fail on Linux ("no properly formatted checksum lines found"). This script forces LF.
#
# Usage:
#   powershell -File system\scripts\Make-Checksums.ps1                 # all files in the current folder
#   powershell -File system\scripts\Make-Checksums.ps1 -Files a.zip,b.tar.gz
#   powershell -File system\scripts\Make-Checksums.ps1 -Directory .\release -OutFile .\release\SHA256SUMS
param(
    [string[]]$Files,
    [string]$Directory = '.',
    [string]$OutFile
)
$ErrorActionPreference = 'Stop'
if (-not $OutFile) { $OutFile = Join-Path $Directory 'SHA256SUMS' }

if (-not $Files -or $Files.Count -eq 0) {
    # All files in the folder, excluding the SHA256SUMS file itself.
    $outName = [IO.Path]::GetFileName($OutFile)
    $Files = Get-ChildItem -File -Path $Directory |
        Where-Object { $_.Name -ne $outName } |
        ForEach-Object { $_.FullName }
}
if (-not $Files -or $Files.Count -eq 0) { throw 'No files to checksum.' }

$lines = foreach ($f in $Files) {
    if (-not (Test-Path -LiteralPath $f)) { throw "File not found: $f" }
    $hash = (Get-FileHash -LiteralPath $f -Algorithm SHA256).Hash.ToLower()
    $name = [IO.Path]::GetFileName($f)
    # sha256sum format: <hash><2 spaces><file name>
    "$hash  $name"
}

# Write UTF-8 without BOM, LF-only line endings, and a trailing LF.
$text = ($lines -join "`n") + "`n"
[IO.File]::WriteAllText($OutFile, $text, (New-Object Text.UTF8Encoding($false)))
Write-Host "SHA256SUMS written (LF): $OutFile"
$lines | ForEach-Object { Write-Host "  $_" }
